  if (hasEntry && !hasSenior) {
    return 'entry';
  }

  if (hasSenior) {
    return 'senior';
  }

  if (/\b(?:software engineer|developer|analyst|specialist|designer|consultant)\b/i.test(combined)) {
    return 'mid';
  }

  return 'uncertain';
};
  const helper = function normalizeLeverItem(company, item) {
